import sys
from collections import deque

def solve():
    data = sys.stdin.read().split()
    if not data:
        return

    iterator = iter(data)

    try:
        h = int(next(iterator))
        t = int(next(iterator))
        R = int(next(iterator))

        n = int(next(iterator))
        head_growth = []
        for _ in range(n):
            hi = int(next(iterator))
            ti = int(next(iterator))
            head_growth.append((hi, ti))

        m = int(next(iterator))
        tail_growth = []
        for _ in range(m):
            hi = int(next(iterator))
            ti = int(next(distinct_iterator := iterator))
            tail_growth.append((hi, ti))
    except StopIteration:
        return

    if h == 0 and t == 0:
        print("Ivan")
        print(0)
        return

    INF = float('inf')
    dist = {}
    queue = deque()

    start_state = (h, t)
    dist[start_state] = 0
    queue.append(start_state)

    can_win = False
    min_blows_to_win = INF
    max_survival = 0

    while queue:
        curr_h, curr_t = queue.popleft()
        d = dist[(curr_h, curr_t)]

        if d > max_survival:
            max_survival = d

        if curr_h == 0 and curr_t == 0:
            can_win = True
            if d < min_blows_to_win:
                min_blows_to_win = d
            continue

        total = curr_h + curr_t
        if total > R:
            continue

        moves = []

        if curr_h > 0:
            max_cut_h = min(n, curr_h)
            for k in range(1, max_cut_h + 1):
                new_h = curr_h - k + head_growth[k-1][0]
                new_t = curr_t + head_growth[k-1][1]
                if new_h + new_t <= R:
                    moves.append((new_h, new_t))

        if curr_t > 0:
            max_cut_t = min(m, curr_t)
            for k in range(1, max_cut_t + 1):
                new_h = curr_h + tail_growth[k-1][0]
                new_t = curr_t - k + tail_growth[k-1][1]
                if new_h + new_t > 0:
                    moves.append((new_h, new_t))
                else:
                    moves.append((0, 0))

        if not moves:
            continue

        for nh, nt in moves:
            if (nh, nt) not in dist:
                dist[(nh, nt)] = d + 1
                queue.append((nh, nt))

    if can_win:
        print("Ivan")
        print(min_blows_to_win)
    else:
        print("Zmey")
        print(max_survival)

solve()
